    // Lazy por icono: abrir una bandeja no construye el catálogo entero.
    private val vectors = glyphs.mapValues { (id, glyph) -> lazy { vector("Studio $id", glyph.path) } }
    operator fun get(id: String): ImageVector = vectors.getValue(id).value

    internal fun vector(name: String, path: String): ImageVector =
        ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).addPath(
            pathData = PathParser().parsePathString(path).toNodes(),
            stroke = SolidColor(Color.White), strokeLineWidth = 1.7f,
            strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
        ).build()
}
